import{_ as e,o as r,c as a,a2 as o}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"PepperCraft 玩家文档","description":"","frontmatter":{},"headers":[],"relativePath":"intro.md","filePath":"intro.md"}'),d={name:"intro.md"};function l(n,t,h,c,s,i){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="peppercraft-玩家文档" tabindex="-1">PepperCraft 玩家文档 <a class="header-anchor" href="#peppercraft-玩家文档" aria-label="Permalink to &quot;PepperCraft 玩家文档&quot;">​</a></h1><blockquote><p>适用版本：PepperCraft 生产服（<strong>26.3</strong>） 资料截止：<strong>2026-10-26</strong> 本文依据服务器实际设置整理，不沿用旧文档；后续版本变更会更新本文。</p></blockquote><hr><h2 id="服务器信息" tabindex="-1">服务器信息 <a class="header-anchor" href="#服务器信息" aria-label="Permalink to &quot;服务器信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>服务器地址</td><td><strong>pepper.ltd</strong>（Java 版端口 25565，基岩版端口 19132）</td></tr><tr><td>服务器 QQ 群</td><td><strong>754966689</strong></td></tr><tr><td>官网</td><td><a href="http://web.pepper.ltd" target="_blank" rel="noreferrer">http://web.pepper.ltd</a></td></tr><tr><td>支持版本</td><td><strong>1.21 及以上</strong>，建议使用较新版本</td></tr><tr><td>文档开源地址</td><td><a href="https://github.com/nullpepper/PepperServer-Document/" target="_blank" rel="noreferrer">GitHub</a></td></tr></tbody></table><h2 id="命令书写约定" tabindex="-1">命令书写约定 <a class="header-anchor" href="#命令书写约定" aria-label="Permalink to &quot;命令书写约定&quot;">​</a></h2><ul><li><code>&lt;xxx&gt;</code> 表示<strong>必填参数</strong>。</li><li><code>[xxx]</code> 表示<strong>可选参数</strong>。</li><li><code>&lt;a|b&gt;</code> 表示从列出的几个值里<strong>选一个</strong>。</li><li><code>A / B</code> 表示同一命令的别名，两种写法完全等价。</li></ul><p>例如命令 <code>/tpa &lt;玩家&gt;</code> 意味着你需要把 <code>&lt;玩家&gt;</code> 替换成一个真实的玩家名。假设要传送到名为 Pepper 的玩家身边：</p><table tabindex="0"><thead><tr><th>写法</th><th>是否正确</th></tr></thead><tbody><tr><td><code>/tpa Pepper</code></td><td>✅</td></tr><tr><td><code>/tpa &lt;Pepper&gt;</code></td><td>❌</td></tr><tr><td><code>/tpa &lt;玩家&gt;</code></td><td>❌</td></tr></tbody></table><h2 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h2><p>刚进服务器？跟着这几步就能开玩：</p><ol><li><strong>回主城确认状态</strong>：输入 <code>/spawn</code>。主城是安全区，禁止 PvP。</li><li><strong>出发去主世界</strong>：在主城输入 <code>/ej</code>，5 秒倒计时后弹射到主世界以 <code>(0,0)</code> 为圆心、半径 1000 格的随机落点；弹射会附带一次摔落保护（从弹射起算 20 秒，落地即用掉）。</li><li><strong>圈一块自己的地</strong>：手持<strong>普通金锄</strong>（自己合成即可），左键点第一个角、右键点对角，然后输入 <code>/pclaim create &lt;名字&gt;</code>。</li><li><strong>设传送点</strong>：<code>/sethome home</code> 设个人传送点，之后 <code>/home home</code> 就能回来；在自己领地里输入 <code>/pclaim settp</code> 可设领地传送点。</li><li><strong>认识经济</strong>：服务器货币是<strong>钻石</strong>，新玩家初始有 8 钻石。用 <code>/balance</code> 查看余额，用 <code>/bank</code> 打开钻石银行界面存取。</li><li><strong>与人交流</strong>：<code>/msg &lt;玩家&gt; &lt;消息&gt;</code> 私聊，<code>/tpa &lt;玩家&gt;</code> 请求传送到对方身边。</li></ol><p>遇到问题先看 <a href="./faq.html">已知限制与常见问题</a>，也可以加入 QQ 群提问。</p><h2 id="文档导航" tabindex="-1">文档导航 <a class="header-anchor" href="#文档导航" aria-label="Permalink to &quot;文档导航&quot;">​</a></h2><ul><li><strong>基础</strong>：<a href="./connection.html">连接与快速开始</a> · <a href="./rules.html">基础设定与游戏规则</a> · <a href="./chat.html">聊天与社交</a> · <a href="./teleport.html">传送与个人传送点</a> · <a href="./economy.html">经济系统</a></li><li><strong>领地与联盟</strong>：<a href="./claims.html">个人领地</a> · <a href="./union.html">联盟</a></li><li><strong>玩法</strong>：<a href="./harvest.html">连锁采集</a> · <a href="./minecart.html">矿车工作站</a> · <a href="./eject.html">主城弹射</a> · <a href="./titles.html">称号系统</a> · <a href="./actions.html">休闲动作</a></li><li><strong>其他</strong>：<a href="./bedrock.html">基岩版与跨版本</a> · <a href="./commands.html">命令速查表</a> · <a href="./faq.html">已知限制与常见问题</a> · <a href="./reference.html">快速参考卡</a></li></ul><p>从左侧目录选择章节，或按顺序阅读。</p>',16)])])}const m=e(d,[["render",l]]);export{g as __pageData,m as default};
